INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63389003', 63389003, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN LANJUTAN', 'Jasa Konsultasi Penyusunan Pedoman Teknis Pemenuhan Peralatan Kesehatan Layanan Kesehatan Jiwa', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 100000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Belanja Jasa Konsultan; Jasa Konsultasi Penyusunan Pedoman Teknis Pemenuhan Peralatan Kesehatan Layanan Kesehatan Jiwa Uraian pekerjaan meliputi penyusunan Pedoman Teknis Peralatan Kesehatan Layanan Kesehatan Jiwa sebagai Norma, Standar, Prosedur, dan Kriteria (NSPK). Kegiatan mencakup persiapan, pengumpulan dan pengkajian data, penyusunan draf pedoman, pembahasan dan harmonisasi dengan pemangku kepentingan terkait, finalisasi dokumen, serta diseminasi pedoman. Pekerjaan dilaksanakan untuk mendukung pemenuhan peralatan kesehatan layanan kesehatan jiwa sesuai stratifikasi kemampuan rumah sakit jejaring pengampuan.', 'Spesifikasi pekerjaan berupa jasa konsultansi profesional untuk penyusunan pedoman teknis peralatan kesehatan layanan kesehatan jiwa yang komprehensif dan berbasis regulasi. Output berupa satu dokumen Pedoman Teknis Peralatan Kesehatan Layanan Kesehatan Jiwa yang memuat standar peralatan sesuai stratifikasi layanan (madya, utama, dan paripurna). Pelaksanaan pekerjaan mengacu pada ketentuan peraturan perundang-undangan di bidang kesehatan dan rumah sakit, dengan spesifikasi teknis dan metodologi pelaksanaan secara rinci ditetapkan dalam Kerangka Acuan Kerja (KAK) dan dokumen pemilihan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 900334);
