INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63368356', 63368356, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS SUMBER DAYA AIR', 'Pengelolaan Sarana dan Prasarana Waduk Dukuh 2, Waduk Dukuh 1, Waduk Munjul, Waduk Cimanggis, dan Waduk Aseni', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Barat (Kota) | DKI Jakarta, Jakarta Timur (Kota)', 3824023363, 'January 2026', 'APBD', 1, 1, '1 Paket', '1. Merawat serta membersihkan sarana dan prasarana waduk seperti pos jaga, toilet, tempat ibadah, kontainer (apabila ada), jalan inspeksi/jogging track, taman bermain anak, serta sarana dan prasarana waduk/situ/embung lainnya. 2. Melakukan pengoperasian mesin press sampah, mesin pencacah, nanobubble, dan aerator sesuai dengan SOP (apabila ada). 3. Inspeksi rutin untuk memantau kondisi dinding penahan tanah waduk. 4. Merawat tanaman pada area dinding penahan tanah dan ruang terbuka hijau termasuk penanaman pohon/tanaman kembali untuk yang sudah mati. 5. Perawatan rutin tanggul waduk meliputi pengecekan retakan tanggul, kebocoran tanggul, pembersihan dari sampah dan vegetasi seperti eceng gondok dan tanaman liar lainnya 6. Perawatan rutin pagar pembatas area waduk berupa pagar panel beton dan/ atau pagar BRC beserta pintu gerbang dengan melakukan pengecekan dan pendataan kondisi pondasi pagar/pintu pagar, keretakan panel beton dan perawatan dari aksi vandalisme dan kriminalisme. 7. Pengamanan area waduk dengan menjaga ketertiban dan keamanan waduk/situ/embung dari pengunjung, kendaraan serta para pedagang, menertibkan pengunjung waduk yang menyalahi aturan dan menegakkan aturan jam kunjung waduk serta melakukan pengamanan terhadap asset sarana dan prasarana waduk selama 24 jam. 8. Melakukan identifikasi kerusakan sarana dan prasarana waduk/situ/embung dalam skala sedang dan besar untuk dilaporkan kepada PPK. 9. Mengimplementasikan Kesehatan dan Keselamatan Kerja selama melaksanakan tugas pemeliharaan waduk/situ/embung. 10. Menyusun laporan harian pelaksanaan pekerjaan seluruh personil. 11. Menyusun laporan akhir pelaksanaan pekerjaan pemeliharaan waduk. 12. Pengadaan Pakaian Kerja untuk petugas Pemeliharaan Waduk. 13. Pengadaan Peralatan Kerja untuk menunjang kegiatan Pemeliharaan. 14. Biaya rutin bulanan seperti pengangkutan sampah, bensin, oli, Listrik, wifi, dan kebutuhan rutin lainnya. 15. Menyediakan Peralatan Kerja pendukung pemeliharaan dan material / bahan habis pakai sesuai kebutuhan.', '1. Menjaga dan meningkatkan kualitas kebersihan lingkungan kawasan waduk. 2. Memelihara keindahan, kerapihan, dan estetika taman di sekitar waduk. 3. Memelihara kondisi sarana dan prasarana pendukung kawasan waduk agar tetap berfungsi dengan baik. 4. Mewujudkan kawasan waduk dan taman yang tertata, aman, dan nyaman.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 2, 902157);
